with d as (select value r from jsonb_array_elements($q$[{"notes":["Make ahead: marinate the meat for up to 4 hours in the fridge, and caramelise the onions an hour before cooking.","The dum pukht (sealed steaming) is essential, resist the urge to open the lid. This is where the magic happens.","Some cooks add saffron soaked in warm milk to the rice before the final layer. If you have it, scatter 1 tsp saffron threads soaked in 100 ml warm milk over the meat layer.","Food safety: Braised beef and lamb cook well past 75°C on the way to tender, so they are safe once soft."],"id":"98c52227-0c5c-4d2c-b801-20cec8b277f1"},{"notes":["Food safety: Cook mince and sausages until no pink remains and the centre reaches 75°C."],"id":"1188e19f-42c5-4b3a-ac9d-c32c9c3d22f3"},{"notes":["The stock is the soul of this soup. If you don't have time to make your own, use a good-quality shop-bought beef stock, but warm it through gently, never let it boil hard.","Some cooks add a small handful of minced beef cooked separately; cooking it in the pot is simpler, and either way works.","Food safety: Braised beef and lamb cook well past 75°C on the way to tender, so they are safe once soft."],"id":"347c5d46-f63c-47d6-aa3d-ef8f87db2927"},{"steps":[{"text":"Bring a pot of water to a rolling boil, until large bubbles break the surface constantly, and add the salt."},{"text":"Add the edamame and return to a boil, then cook until the pods are bright green and the beans are tender."},{"text":"Cook for 5 minutes if fresh, 4 minutes if frozen, until bright green and tender."},{"text":"Drain in a colander and cool slightly."},{"text":"Transfer to a bowl and serve. Squeeze the beans out of the pods into your mouth as you eat."}],"id":"72ac71c8-d722-4519-a549-89124c6a930b"},{"diets":["no-gluten"],"notes":["Make it a day ahead and reheat gently at 160°C for 20 minutes, the flavours marry beautifully overnight.","Short on time? Buy good passata instead of tinned tomatoes and skip the simmering step.","If you can't find fresh mozzarella, use half the quantity of low-moisture mozzarella and mix it with the parmesan.","For a vegetarian version, use a vegetarian hard cheese (made without animal rennet)."],"steps":[{"text":"Arrange eggplant slices on a clean tea towel or paper towels. Sprinkle both sides generously with salt and let sit for 15 minutes to draw out moisture. Pat dry thoroughly."},{"text":"While the eggplant rests, heat the tomato sauce: warm 2 tbsp of the oil in a large pan over medium heat. Add minced garlic and cook for 30 seconds until fragrant. Add tinned tomatoes, breaking them up with a wooden spoon. Tear in most of the basil leaves (reserve a few for garnish). Simmer for 10 minutes, stirring occasionally. Season with salt and pepper. Set aside."},{"text":"Heat the remaining oil in a large frying pan over medium-high heat. Once hot, fry eggplant slices in batches for 3–4 minutes per side until golden brown and soft. Transfer to paper towels to drain. Don't crowd the pan; let them cook in a single layer."},{"text":"Preheat the oven to 180°C."},{"text":"Spread a thin layer of tomato sauce over the base of a 23 × 33 cm baking dish. Arrange a layer of fried eggplant slices over the sauce, overlapping slightly. Top with a layer of fresh mozzarella, then a sprinkle of grated parmesan. Repeat the layers, sauce, eggplant, mozzarella, parmesan, until everything is used, ending with a good handful of parmesan on top."},{"text":"Bake uncovered for 30–35 minutes until the top is golden and bubbling at the edges. Let rest for 5 minutes before serving. Tear over the reserved fresh basil."}],"id":"95ebfa5e-0ef3-48ef-a057-fbb8b947c50b"},{"steps":[{"text":"Heat the oil in a large frying pan over medium-high heat. Add the sliced onion and cook for 2–3 minutes, stirring, until just softened."},{"text":"Add the chopped squash blossoms and a pinch of salt. Cook for 3–4 minutes, stirring gently, until the flowers have wilted and released their moisture. The mixture should be tender but not mushy. Taste and adjust salt."},{"text":"Warm the corn tortillas in a dry frying pan or directly over a gas flame for 15 seconds each, or wrap them in a damp tea towel to keep them soft."},{"text":"Divide the squash blossom filling between the tortillas, placing it on one half of each. Top the filling with pieces of cheese, then fold the tortilla in half."},{"text":"In a clean frying pan, heat a little oil over medium-high heat. Fry the quesadillas for 1–2 minutes per side until they are warmed through and the cheese begins to soften. Don't cook them so long the tortilla becomes crisp, they should stay tender."},{"text":"Serve immediately with salsa verde and a squeeze of fresh lime."}],"id":"cb66f7f2-81b7-4454-9f7f-d40785bd0b85"},{"notes":["Make it ahead: fry the rice earlier in the day and reheat gently, or serve at room temperature. Both sambals keep 2 days in the fridge.","Stretch it: add more veg sides like pickled papaya, blanched long beans or leftover roasted vegetables. Boiled egg, leftover chicken, or fried tofu work just as well as tempeh.","Food safety: Cool any leftover rice quickly and refrigerate it within an hour; reheat it until steaming hot."],"steps":[{"text":"Make sambal matah: toss the sliced shallots and chillies with lime juice and salt, then pour over the hot oil and set aside to infuse."},{"text":"Make sambal terasi: pound the chillies, shrimp paste, garlic and salt into a rough paste in a mortar, then stir through lime juice. (Or blend if you prefer it smoother.)"},{"text":"Heat the oil in a large pan over medium-high heat. Add the minced garlic and cook for 30 seconds until fragrant, then add the cooled rice, breaking up any lumps as it fries, about 5 minutes."},{"text":"Stir through the spring onions, season with salt and white pepper to taste, and remove from heat."},{"text":"Form the fried rice into small mounds on a large serving platter, each person gets 2 or 3 little portions to build on."},{"text":"Arrange the tempeh, cucumber and tomato around the rice, and put both sambals in small bowls alongside. Everyone builds their own plate, taking a mound of rice and topping it with sambal, tempeh and veg as they like."}],"id":"bb53646b-ebed-4f8a-9435-d41a6ff61e34"},{"notes":["Stockfish must be soaked in cold water for at least 4 hours (or overnight) before use, then flaked or shredded. Ask for it at West African or Asian grocers.","Make this soup in a big batch on Sunday and refrigerate for up to 3 days. Reheat gently and add a splash of water if it's thickened too much.","The okra will release plenty of slime, that's what makes the soup silky and satisfying. Stir it well as it cooks.","Food safety: Cook fish until it is opaque and flakes easily (63°C in the thickest part), and prawns until pink and opaque all the way through."],"steps":[{"text":"Heat the palm oil in a large pot over medium heat. Add the chopped onion and cook, stirring, until soft, about 3 minutes."},{"text":"Add the minced garlic and ginger, stir for 1 minute until fragrant."},{"text":"Stir in the tomato paste and cook for 2 minutes, breaking it down into the oil."},{"text":"Add the shredded stockfish and stir to coat. Cook for 3 minutes."},{"text":"Pour in the chicken stock and bring to a gentle simmer. Cook for 15 minutes, stirring occasionally."},{"text":"Add the sliced okra and stir well, don't worry if it looks very slimy at first. Simmer for 10 minutes."},{"text":"Add the prawns and ground crayfish if using. Simmer for another 8–10 minutes until the prawns are pink and cooked through."},{"text":"Taste and season with salt and black pepper. The soup should be thick and slippery. Serve hot over fufu."}],"id":"ec19ae6a-04a8-497a-b9d1-694848827576"},{"notes":["You can prepare the breaded chicken parcels up to 4 hours ahead and refrigerate them before frying. This helps them stay together and cook evenly.","If the oil is too hot, the coating will brown too quickly before the chicken cooks through. If it's not hot enough, the chicken will absorb oil and become greasy rather than crisp.","Serve with boiled potatoes and a simple salad of beetroot and dill, if you like.","Food safety: Cook chicken (and other poultry) until the thickest part reaches 75°C and the juices run clear, with no pink meat near the bone."],"steps":[{"text":"Mix the softened butter with minced garlic, fresh dill, salt and a pinch of black pepper. Divide into 4 portions and shape each into a small block. Freeze for at least 15 minutes until firm."},{"text":"Place each chicken breast between two sheets of plastic wrap. Using a meat mallet or rolling pin, pound gently but firmly until the breast is about 5 mm thick. Work from the centre outwards, being careful not to tear the meat."},{"text":"Lay one flattened chicken breast on a clean surface. Place a butter portion in the centre. Fold the long sides over the butter, then fold in the short sides to seal, creating a neat parcel. The seam should be on the bottom."},{"text":"Place the flour on one plate, beaten eggs in a shallow bowl, and breadcrumbs on another plate. Coat each chicken parcel lightly in flour, shaking off excess. Dip in beaten egg to coat completely, then roll in breadcrumbs until fully covered. Place on a plate, seam-side down."},{"text":"Heat the oil in a large, heavy-based frying pan over medium-high heat until a breadcrumb sizzles immediately when dropped in (about 160°C)."},{"text":"Carefully place the chicken parcels seam-side up into the hot oil. Fry for 5 to 6 minutes until the breadcrumb coating is deep golden brown, then gently turn and fry the other side for another 4 to 5 minutes until crisp and the internal temperature reaches 75°C."},{"text":"Remove with a slotted spoon and drain on paper towels. Let rest for 2 minutes before serving. The butter inside will be hot, warn your family to cut carefully so they don't get splashed."}],"id":"6dde5f03-a13a-477b-8d70-20fef973cdab"},{"notes":["Stinky tofu (chou doufu) is the star here, its pungent, funky smell is what makes it special. Find it in the refrigerated section of Asian grocers, often near the fresh tofu.","The tofu needs to be truly crispy outside to contrast with the QQ creamy interior. Don't skip the cornflour coating or lower the oil temperature.","Pickled mustard greens (xue cai) cut through the richness beautifully, swap for pickled daikon if you prefer something milder."],"steps":[{"text":"Toss the stinky tofu cubes gently with cornflour and salt until coated."},{"text":"Heat about 2 cm of neutral oil in a shallow pan or wok to 180°C. Test with a wooden chopstick, it should bubble gently around it."},{"text":"Working in two batches, carefully slide the tofu into the hot oil. Fry for 4–5 minutes, turning once, until the outside is golden and crispy and the edges are bubbling. Drain on paper towels."},{"text":"While the tofu fries, stir together the chilli sauce, soy sauce, sugar and 1 tbsp water in a small bowl."},{"text":"Serve the hot tofu with pickled mustard greens on the side, the chilli sauce for dipping, and spring onion scattered over. Eat while it's still crackling."}],"id":"301ad861-b33c-4a0d-83d2-ffcc47b38917"},{"notes":["Make the sambal paste in advance (up to 2 days ahead) and store in an airtight container in the fridge. Bring it to room temperature before rubbing it on the chicken.","For less heat, use 1 or 2 chillies instead of 3. For more punch, add a bird's eye chilli or two.","Leftovers keep in an airtight container in the fridge for up to 3 days and are just as good cold the next day.","Food safety: Cook chicken (and other poultry) until the thickest part reaches 75°C and the juices run clear, with no pink meat near the bone."],"steps":[{"text":"Make the sambal paste: Combine the shallots, garlic, chillies, candlenuts, tamarind paste and salt in a food processor. Pulse until you have a coarse, chunky paste, not smooth. Heat 2 tbsp neutral oil in a pan over medium heat, add the paste and fry, stirring often, for about 5 minutes until it darkens and smells fragrant. Let it cool slightly."},{"text":"Pat the chicken thighs dry with paper towel. Rub them all over with the cooled sambal paste, turmeric and coriander, working it into the skin and under it where you can. Ideally sit the chicken in a bowl for 30 minutes to an hour, but even 10 minutes helps."},{"text":"Heat about 300 ml neutral oil in a large, heavy-based pan or wok over medium-high heat. Test the heat with a small piece of shallot, it should sizzle immediately."},{"text":"Working in batches so you don't overcrowd the pan, carefully place the chicken skin-side down into the hot oil. Fry for 6–7 minutes until the skin is deep golden and crisps up, shaking the pan occasionally so it colours evenly."},{"text":"Flip each piece and fry the other side for another 6–7 minutes until golden. The chicken should be cooked through, cut into the thickest thigh near the bone and check there's no pink; if unsure, the inside should reach 75°C."},{"text":"Transfer the cooked chicken to a plate lined with paper towel to drain. Taste one piece and season with a pinch more salt if needed. Serve hot."}],"id":"ae8bc566-4d6f-440d-abef-2d2b7a80176b"},{"steps":[{"text":"Get your braai hot, you want the coals glowing and ready."},{"text":"Tear off a large piece of foil and lay the snoek in the middle. Season inside and out with salt and pepper."},{"text":"Stuff the cavity with half the garlic slices and half the lemon slices. Top with a knob of butter."},{"text":"Scatter the remaining garlic and lemon over the top, then dot with the last of the butter. Wrap the foil loosely around the fish, sealing it well so the steam stays inside, and bake until the fish is opaque and flakes easily with a fork."},{"text":"Place the parcel on the hot coals and cook for about 10 to 12 minutes, until the flesh is opaque and flaking away from the bones."},{"text":"Carefully unwrap the foil, watch the steam, and check that the fish is opaque and flakes easily. Slide the fish onto a plate. Spoon the buttery juices from the foil over the top."}],"id":"c3ec5d64-4517-40ee-aac6-ebae8eb15361"},{"notes":["Make this a day ahead if you like, it keeps well in the fridge for up to 3 days.","Lucía sometimes stirs in a splash of water to loosen it on the day if it's thickened overnight.","Serve with small glasses of ice water on the side, or pour into shallow bowls if you're feeling elegant."],"steps":[{"text":"Place the tomatoes, capsicum, cucumber and garlic in a large bowl. Pour over the olive oil and sherry vinegar, and add a pinch of salt. Let sit for 10 minutes to release the juices."},{"text":"In batches, blend the vegetables and oil until completely smooth, this is a sieve-smooth gazpacho, not a chunky one. Pass the blended mixture through a fine sieve into a clean bowl, pressing gently to extract all the liquid. Discard the pulp."},{"text":"Stir in the ice water to cool and lighten the soup. Taste and adjust the salt and vinegar to your liking."},{"text":"Cover and refrigerate for at least 2 hours, or until well chilled. Serve ice cold in small glasses or shallow bowls."}],"id":"54053b44-7952-4d3f-9750-749b514e4b3b"},{"notes":["Base genep keeps in the fridge for up to 5 days, or freeze in ice-cube trays for up to 3 months.","If you don't have fresh turmeric, use 1 tsp ground turmeric instead.","A mortar and pestle gives the best flavour and texture, but you can use a food processor if needed, pulse until smooth, then stir through the lime and salt by hand."],"id":"31791570-be7b-48e7-a97e-8153ba976bb8"},{"notes":["Use day-old or cooled cooked rice, freshly cooked rice will clump and steam instead of fry.","Shrimp paste is pungent raw but mellows when cooked with oil and the other ingredients. Start with 1 tbsp and adjust to taste.","Double this easily if you're cooking for two, but it's designed for one burner and one wok.","Food safety: Cook chicken and other poultry until the juices run clear and the thickest part reaches 75°C."],"id":"3cc11280-f53a-4d0f-aa45-922508bd34e1"}]$q$::jsonb)), up as (update public.published_recipes p set recipe = p.recipe || (d.r - 'id' - 'notes') || case when d.r ? 'notes' then jsonb_build_object('notes', coalesce((select jsonb_agg(n) from jsonb_array_elements(d.r->'notes') n where btrim(n#>>'{}') <> 'Food safety:'),'[]'::jsonb)) else '{}'::jsonb end, diets = case when d.r ? 'diets' then array(select jsonb_array_elements_text(d.r->'diets')) else p.diets end from d where p.id=(d.r->>'id')::uuid returning p.id) select (select count(*) from d) expected, (select count(*) from up) updated;